// ===== agenda-dinamica.js =====
function initDynamicAgenda(){
  const section = qs('#agenda');
  const list = qs('[data-agenda-list]', section || document);
  const status = qs('[data-agenda-sync-status]', section || document);
  if(!section || !list) return;

  const endpoint = (section.dataset.agendaApiUrl || '').trim();
  const configured = endpoint &&
    !endpoint.includes('COLE_AQUI') &&
    /^https:\/\/script\.google\.com\/macros\/s\/.+\/exec(?:\?.*)?$/.test(endpoint);

  if(!configured){
    if(status){
      status.innerHTML = '<i class="fa-solid fa-circle-info" aria-hidden="true"></i> Agenda exibida a partir da versão publicada no site. Configure a integração com o Google Sheets para atualização automática.';
    }
    return;
  }

  const create = (tag, className, text) => {
    const element = document.createElement(tag);
    if(className) element.className = className;
    if(text !== undefined && text !== null) element.textContent = text;
    return element;
  };

  const icon = className => {
    const element = document.createElement('i');
    element.className = className;
    element.setAttribute('aria-hidden', 'true');
    return element;
  };

  const appendMeta = (paragraph, iconClass, text) => {
    if(!text) return;
    if(paragraph.childNodes.length) paragraph.append(document.createTextNode('  '));
    paragraph.append(icon(iconClass), document.createTextNode(` ${text}`));
  };

  const renderItem = item => {
    const card = create('article', `agenda-card reveal is-visible${item.fixa ? ' agenda-card--fixed' : ''}`);

    let dateBox;
    if(item.fixa){
      dateBox = create('div', 'agenda-card__date agenda-card__date--fixed');
      dateBox.setAttribute('aria-hidden', 'true');
      dateBox.append(icon('fa-solid fa-repeat'), create('span', '', 'FIXA'));
    }else{
      dateBox = create('time', 'agenda-card__date');
      if(item.data) dateBox.setAttribute('datetime', item.data);
      dateBox.append(
        create('strong', '', item.dia || ''),
        create('span', '', item.mes || '')
      );
    }

    const content = create('div', 'agenda-card__content');

    if(item.fixa){
      const fixedLabel = create('span', 'agenda-card__fixed-label');
      fixedLabel.append(icon('fa-solid fa-thumbtack'), document.createTextNode(' Agenda fixa'));
      content.append(fixedLabel);
    }

    if(item.diaSemana || item.recorrencia){
      content.append(create(
        'span',
        'agenda-card__weekday',
        item.fixa ? (item.recorrencia || item.diaSemana) : item.diaSemana
      ));
    }

    content.append(create('h3', '', item.evento || 'Compromisso da campanha'));

    const meta = create('p');
    appendMeta(meta, 'fa-regular fa-clock', item.horario);
    appendMeta(meta, 'fa-solid fa-location-dot', item.local);
    if(meta.childNodes.length) content.append(meta);

    if(item.observacoes){
      content.append(create('p', 'agenda-card__notes', item.observacoes));
    }

    card.append(dateBox, content);
    return card;
  };

  const render = payload => {
    const items = Array.isArray(payload?.itens) ? payload.itens : [];

    if(!items.length){
      list.replaceChildren();
      const empty = create('div', 'agenda__empty');
      empty.append(
        icon('fa-regular fa-calendar'),
        create('strong', '', 'Novos compromissos serão divulgados em breve.'),
        create('span', '', 'A equipe da campanha está atualizando a agenda.')
      );
      list.append(empty);
    }else{
      const fragment = document.createDocumentFragment();
      items.forEach(item => fragment.append(renderItem(item)));
      list.replaceChildren(fragment);
    }

    if(status){
      const updated = payload?.ultimaAtualizacao
        ? ` Atualizada em ${payload.ultimaAtualizacao}.`
        : '';
      status.innerHTML = `<i class="fa-solid fa-circle-check" aria-hidden="true"></i> Agenda sincronizada automaticamente com a equipe da campanha.${updated}`;
      status.classList.add('is-synced');
    }

    try{
      localStorage.setItem('fabiano13007_agenda_cache', JSON.stringify({
        savedAt: Date.now(),
        payload
      }));
    }catch(_){}
  };

  const useCachedFallback = () => {
    try{
      const cached = JSON.parse(localStorage.getItem('fabiano13007_agenda_cache') || 'null');
      if(cached?.payload?.itens){
        render(cached.payload);
        if(status){
          status.innerHTML = '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Exibindo a última agenda sincronizada. A atualização online será tentada novamente no próximo acesso.';
          status.classList.remove('is-synced');
          status.classList.add('is-fallback');
        }
        return true;
      }
    }catch(_){}
    return false;
  };

  const callbackName = `fabianoAgenda_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const script = document.createElement('script');
  let finished = false;

  const cleanup = () => {
    window.clearTimeout(timeout);
    script.remove();
    try{ delete window[callbackName]; }catch(_){ window[callbackName] = undefined; }
  };

  window[callbackName] = payload => {
    if(finished) return;
    finished = true;
    cleanup();

    if(payload?.ok === false){
      if(!useCachedFallback() && status){
        status.innerHTML = '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Não foi possível atualizar a agenda agora. Mantivemos a programação publicada no site.';
        status.classList.add('is-fallback');
      }
      return;
    }

    render(payload);
  };

  const separator = endpoint.includes('?') ? '&' : '?';
  script.src = `${endpoint}${separator}callback=${encodeURIComponent(callbackName)}&_=${Date.now()}`;
  script.async = true;
  script.onerror = () => {
    if(finished) return;
    finished = true;
    cleanup();
    if(!useCachedFallback() && status){
      status.innerHTML = '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Não foi possível sincronizar a agenda agora. Mantivemos a programação publicada no site.';
      status.classList.add('is-fallback');
    }
  };

  const timeout = window.setTimeout(() => {
    if(finished) return;
    finished = true;
    cleanup();
    if(!useCachedFallback() && status){
      status.innerHTML = '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> A sincronização demorou além do esperado. Mantivemos a programação publicada no site.';
      status.classList.add('is-fallback');
    }
  }, 10000);

  document.head.append(script);
}




// ===== foto-apoiador.js =====
function initSupporterPhotoCreator() {
  const openButton = qs('#supporter-photo-open');
  const wizard = qs('#supporter-photo-wizard');
  if (!openButton || !wizard) return;

  const closeButtons = qsa('[data-wizard-close]');
  const stepPanels = qsa('[data-wizard-step]');
  const nextButton = qs('#supporter-wizard-next');
  const backButton = qs('#supporter-wizard-back');
  const progressFill = qs('#supporter-wizard-progress-fill');
  const progressText = qs('#supporter-wizard-progress-text');

  const input = qs('#supporter-wizard-input');
  const fileInfo = qs('#supporter-wizard-file-info');
  const formatButtons = qsa('[data-wizard-format]');

  const previewCanvas = qs('#supporter-wizard-preview');
  const editorCanvas = qs('#supporter-wizard-editor');
  const finalCanvas = qs('#supporter-wizard-final');
  const finalCanvasStep6 = qs('#supporter-wizard-final-step6');
  const previewFrame = qs('[data-wizard-preview-frame]');
  const editorFrame = qs('[data-wizard-editor-frame]');
  const finalFrame = qs('[data-wizard-final-frame]');

  const zoom = qs('#supporter-wizard-zoom');
  const zoomValue = qs('#supporter-wizard-zoom-value');
  const resetButton = qs('#supporter-wizard-reset');
  const shareButton = qs('#supporter-wizard-share');
  const status = qs('#supporter-wizard-status');
  const saveButton = qs('#supporter-wizard-save');
  const saveStatus = qs('#supporter-wizard-save-status');
  const desktopShareButtons = qsa('[data-desktop-share]');
  const desktopShareStatus = qs('#supporter-wizard-share-status');
  const mobileSaveButton = qs('#supporter-wizard-mobile-save');
  const mobileSaveStatus = qs('#supporter-wizard-mobile-save-status');
  const mobileShareButtons = qsa('[data-mobile-share]');
  const mobileShareStatus = qs('#supporter-wizard-mobile-share-status');
  const profileSaveStep = qs('.supporter-wizard__profile-save-step');
  const profileNetworksStep = qs('.supporter-wizard__profile-networks-step');
  const desktopSaveStep = qs('.supporter-wizard__desktop-save-step');
  const mobileSaveStep = qs('.supporter-wizard__mobile-save-step');
  const desktopShareStep = qs('.supporter-wizard__desktop-share-step');
  const mobileShareStep = qs('.supporter-wizard__mobile-share-step');
  const step6Kicker = qs('[data-step6-kicker]');
  const step6Title = qs('[data-step6-title]');
  const step6Description = qs('[data-step6-description]');
  const step6Number = qs('[data-wizard-step="6"] .supporter-wizard__step-number');
  const captionCopyContinueButton = qs('#supporter-wizard-caption-copy-continue');
  const captionSkipButton = qs('#supporter-wizard-caption-skip');
  const captionChoiceStatus = qs('#supporter-wizard-caption-status');
  const copyCaptionStep6Button = qs('#supporter-wizard-copy-caption-step6');
  const copyCaptionStep6MobileButton = qs('#supporter-wizard-copy-caption-step6-mobile');
  const profileSaveButton = qs('#supporter-wizard-profile-save');
  const profileSaveStatus = qs('#supporter-wizard-profile-save-status');
  const profileNetworkButtons = qsa('[data-profile-network]');

  if (!input || !previewCanvas || !editorCanvas || !finalCanvas || !zoom) return;

  const ctx = editorCanvas.getContext('2d');
  const photo = new Image();
  // Artes incorporadas como data URLs para manter o canvas exportável também quando o site é aberto via file://.
  // Referenciar PNGs locais diretamente pode tornar o canvas 'tainted' em alguns navegadores e bloquear toBlob/toDataURL.
  const campaignArtPost = new Image();
  const campaignArtStory = new Image();
  const campaignArtProfile = new Image();
  campaignArtPost.src = 'data:image/png;base64,';
  campaignArtStory.src = 'data:image/png;base64,';
  campaignArtProfile.src = 'data:image/png;base64,';
  const specs = {
    feed: { width: 1080, height: 1350, filename: 'eu-apoio-fabiano-13007-post.png' },
    story: { width: 1080, height: 1920, filename: 'eu-apoio-fabiano-13007-story.png' },
    profile: { width: 1080, height: 1080, filename: 'eu-apoio-fabiano-13007-perfil.png' }
  };

  let step = 1;
  let objectUrl = '';
  let loaded = false;
  let selectedFormat = '';
  let captionChoice = null;
  const isProfileFlow = () => selectedFormat === 'profile';
  const visibleStepNumber = () => (isProfileFlow() && step === 6 ? 5 : step);
  const visibleTotalSteps = () => (isProfileFlow() ? 5 : 6);

  let baseScale = 1;
  let zoomFactor = 1;
  let offsetX = 0;
  let offsetY = 0;
  let dragging = false;
  let pointerId = null;
  let lastX = 0;
  let lastY = 0;
  let lastFocusedElement = null;

  const spec = () => specs[selectedFormat || 'feed'];
  const W = () => editorCanvas.width;
  const H = () => editorCanvas.height;

  const setFrameFormat = frame => {
    if (!frame) return;
    frame.dataset.format = selectedFormat || 'feed';
  };

  const setCanvasSize = () => {
    const s = spec();
    [previewCanvas, editorCanvas, finalCanvas].forEach(canvas => {
      canvas.width = s.width;
      canvas.height = s.height;
    });
    [previewFrame, editorFrame, finalFrame].forEach(setFrameFormat);
  };

  const clampOffsets = () => {
    if (!loaded) return;
    const drawnW = photo.naturalWidth * baseScale * zoomFactor;
    const drawnH = photo.naturalHeight * baseScale * zoomFactor;
    const maxX = Math.max(0, (drawnW - W()) / 2);
    const maxY = Math.max(0, (drawnH - H()) / 2);
    offsetX = clamp(offsetX, -maxX, maxX);
    offsetY = clamp(offsetY, -maxY, maxY);
  };

  const drawCampaignArt = () => {
    if (!selectedFormat) return;
    const art = selectedFormat === 'profile'
      ? campaignArtProfile
      : selectedFormat === 'story'
        ? campaignArtStory
        : campaignArtPost;
    if (!(art.complete && art.naturalWidth)) return;

    const w = W();
    const h = H();
    // Each supplied artwork is the complete campaign frame. It is scaled to
    // the selected output format while the transparent area reveals the voter photo.
    ctx.drawImage(art, 0, 0, art.naturalWidth, art.naturalHeight, 0, 0, w, h);
  };

  const render = () => {
    const w = W();
    const h = H();
    ctx.clearRect(0, 0, w, h);

    if (!loaded || !selectedFormat) {
      ctx.fillStyle = '#1B0E0D';
      ctx.fillRect(0, 0, w, h);
    } else {
      clampOffsets();
      const scale = baseScale * zoomFactor;
      const dw = photo.naturalWidth * scale;
      const dh = photo.naturalHeight * scale;
      const x = (w - dw) / 2 + offsetX;
      const y = (h - dh) / 2 + offsetY;

      ctx.drawImage(photo, x, y, dw, dh);

      drawCampaignArt();
    }

    [previewCanvas, finalCanvas, finalCanvasStep6].filter(Boolean).forEach(canvas => {
      const c = canvas.getContext('2d');
      c.clearRect(0, 0, canvas.width, canvas.height);
      c.drawImage(editorCanvas, 0, 0);
    });
  };

  campaignArtPost.addEventListener('load', render);
  campaignArtStory.addEventListener('load', render);
  campaignArtProfile.addEventListener('load', render);

  const resetView = () => {
    if (!loaded || !selectedFormat) return;
    baseScale = Math.max(W() / photo.naturalWidth, H() / photo.naturalHeight);
    zoomFactor = 1;
    offsetX = 0;
    offsetY = 0;
    zoom.value = '100';
    if (zoomValue) zoomValue.value = '100%';
    render();
  };

  const fitActiveStepToViewport = () => {
    const body = qs('.supporter-wizard__body');
    const active = stepPanels.find(panel => Number(panel.dataset.wizardStep) === step);
    if (!body || !active) return;

    active.style.transform = '';
    active.style.transformOrigin = '';
    active.style.width = '';
    active.style.marginInline = '';

    requestAnimationFrame(() => {
      const available = body.clientHeight;
      const needed = active.scrollHeight;

      if (!available || needed <= available) return;

      const minScale = window.matchMedia('(max-width: 820px)').matches ? 0.68 : 0.76;
      const scale = Math.max(minScale, Math.min(1, available / needed));

      active.style.transformOrigin = 'top center';
      active.style.transform = `scale(${scale})`;
      active.style.width = `${100 / scale}%`;
      active.style.marginInline = `${-(100 / scale - 100) / 2}%`;
    });
  };

  const updateNavigation = () => {
    stepPanels.forEach(panel => {
      panel.classList.toggle('is-active', Number(panel.dataset.wizardStep) === step);
    });

    const visibleStep = visibleStepNumber();
    const visibleTotal = visibleTotalSteps();
    const pct = ((visibleStep - 1) / (visibleTotal - 1)) * 100;
    if (progressFill) progressFill.style.width = `${pct}%`;
    if (progressText) progressText.textContent = `Passo ${visibleStep} de ${visibleTotal}`;
    if (backButton) backButton.hidden = step === 1;
    if (nextButton) nextButton.hidden = step === 6;

    if (nextButton) {
      nextButton.disabled =
        (step === 1 && !loaded) ||
        (step === 2 && !selectedFormat) ||
        (step === 5 && !isProfileFlow() && !captionChoice);
    }

    if (step >= 2 && step <= 6) render();

    const isProfileMode = selectedFormat === 'profile';
    document.querySelector('#supporter-photo-wizard')?.classList.toggle('is-profile-mode', isProfileMode);

    if (profileSaveStep) profileSaveStep.hidden = !isProfileMode;
    if (profileNetworksStep) profileNetworksStep.hidden = !isProfileMode;
    if (desktopSaveStep) desktopSaveStep.hidden = isProfileMode;
    if (mobileSaveStep) mobileSaveStep.hidden = isProfileMode;
    if (desktopShareStep) desktopShareStep.hidden = isProfileMode;
    if (mobileShareStep) mobileShareStep.hidden = isProfileMode;

    if (step6Kicker) step6Kicker.textContent = isProfileMode ? 'Próximo passo' : 'Compartilhar';
    if (step6Title) step6Title.textContent = isProfileMode ? 'Agora coloque sua nova foto no perfil' : 'Compartilhe seu apoio';
    if (step6Description) {
      step6Description.textContent = isProfileMode
        ? 'Sua foto já está pronta e salva. Escolha abaixo a rede social em que deseja trocar sua foto de perfil.'
        : 'Agora escolha onde deseja publicar a imagem que você criou.';
    }
    if (step6Number) step6Number.textContent = isProfileMode ? '05' : '06';

    const active = stepPanels.find(panel => Number(panel.dataset.wizardStep) === step);
    fitActiveStepToViewport();
    active?.querySelector('button:not([disabled]), input:not([disabled]), [tabindex="0"]')?.focus({ preventScroll: true });
  };

  const goToStep = newStep => {
    step = clamp(newStep, 1, 6);
    updateNavigation();
  };

  const openWizard = () => {
    lastFocusedElement = document.activeElement;
    wizard.hidden = false;
    wizard.setAttribute('aria-hidden', 'false');
    document.body.classList.add('supporter-wizard-open');
    step = 1;
    captionChoice = null;
    if (status) status.textContent = '';
    updateNavigation();
  };

  const closeWizard = () => {
    wizard.hidden = true;
    wizard.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('supporter-wizard-open');
    lastFocusedElement?.focus?.();
  };

  const loadFile = file => {
    if (!file) return;

    if (!/^image\/(jpeg|png|webp|heic|heif)$/i.test(file.type) && !/\.(jpe?g|png|webp|heic|heif)$/i.test(file.name)) {
      window.alert('Escolha uma imagem JPG, PNG, WEBP, HEIC ou HEIF.');
      input.value = '';
      return;
    }

    if (file.size > 25 * 1024 * 1024) {
      window.alert('Escolha uma foto com até 25 MB.');
      input.value = '';
      return;
    }

    if (objectUrl) URL.revokeObjectURL(objectUrl);
    objectUrl = URL.createObjectURL(file);

    photo.onload = () => {
      loaded = true;
      desktopImageSaved = false;
      if (saveStatus) saveStatus.textContent = '';
      if (fileInfo) {
        fileInfo.hidden = false;
        const label = fileInfo.querySelector('span');
        if (label) label.textContent = file.name;
      }
      if (nextButton && step === 1) nextButton.disabled = false;
    };

    photo.onerror = () => {
      loaded = false;
      window.alert('Não foi possível abrir essa imagem neste navegador. Tente JPG, PNG ou WEBP.');
      input.value = '';
      if (fileInfo) fileInfo.hidden = true;
    };

    photo.src = objectUrl;
  };

  const chooseFormat = format => {
    if (!specs[format]) return;
    selectedFormat = format;
    desktopImageSaved = false;
    if (saveStatus) saveStatus.textContent = '';

    formatButtons.forEach(button => {
      const active = button.dataset.wizardFormat === format;
      button.classList.toggle('is-active', active);
      button.setAttribute('aria-pressed', active ? 'true' : 'false');
    });

    setCanvasSize();
    resetView();

    if (!isProfileFlow()) captionChoice = null;
    if (nextButton && step === 2) nextButton.disabled = false;
    updateNavigation();
  };

  const canvasBlob = () => new Promise((resolve, reject) => {
    try {
      render();

      if (editorCanvas.toBlob) {
        editorCanvas.toBlob(blob => {
          if (blob) {
            resolve(blob);
            return;
          }

          // Fallback for browsers that return null from toBlob.
          try {
            const dataUrl = editorCanvas.toDataURL('image/png');
            fetch(dataUrl).then(r => r.blob()).then(resolve, reject);
          } catch (fallbackError) {
            reject(fallbackError);
          }
        }, 'image/png', 1);
      } else {
        const dataUrl = editorCanvas.toDataURL('image/png');
        fetch(dataUrl).then(r => r.blob()).then(resolve, reject);
      }
    } catch (error) {
      reject(error);
    }
  });

  const forceDownload = async () => {
    render();
    const blob = await canvasBlob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = spec().filename;
    a.style.display = 'none';
    document.body.append(a);
    a.click();
    a.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 4000);
  };


  let desktopImageSaved = false;

  const captionText = `Crie também a sua foto de apoio a Fabiano Trompetista 13007:
https://trompetista13007.com.br/#foto-apoiador

Eu apoio Fabiano Trompetista para Deputado Distrital — 13007.
Coragem para mudar o DF.`;

  const saveImageDesktop = async () => {
    if (!loaded || !selectedFormat) return false;
    render();

    try {
      const blob = await canvasBlob();

      // Chrome/Edge e navegadores compatíveis: permite escolher pasta/nome.
      if ('showSaveFilePicker' in window) {
        try {
          const handle = await window.showSaveFilePicker({
            suggestedName: spec().filename,
            types: [{
              description: 'Imagem PNG',
              accept: { 'image/png': ['.png'] }
            }]
          });

          const writable = await handle.createWritable();
          await writable.write(blob);
          await writable.close();

          desktopImageSaved = true;
          if (saveStatus) saveStatus.textContent = '✓ Imagem salva. Agora escolha onde compartilhar.';
          return true;
        } catch (error) {
          if (error?.name === 'AbortError') {
            if (saveStatus) saveStatus.textContent = 'Salvamento cancelado.';
            return false;
          }
          console.warn('File System Access API indisponível ou falhou:', error);
        }
      }

      // Fallback: download convencional.
      await forceDownload();
      desktopImageSaved = true;
      if (saveStatus) saveStatus.textContent = '✓ Imagem baixada. Agora escolha onde compartilhar.';
      return true;
    } catch (error) {
      console.error('Falha ao salvar imagem:', error);
      if (saveStatus) saveStatus.textContent = 'Não foi possível salvar a imagem. Recarregue a página e tente novamente.';
      return false;
    }
  };

  const ensureDesktopSaved = async () => {
    if (desktopImageSaved) return true;
    if (saveStatus) saveStatus.textContent = 'Salve a imagem antes de abrir a rede social.';
    return await saveImageDesktop();
  };

  const copyCaption = async () => {
    try {
      await navigator.clipboard.writeText(captionText);
      if (desktopShareStatus) desktopShareStatus.textContent = '✓ Legenda copiada para a área de transferência.';
      return true;
    } catch (_) {
      try {
        const textarea = document.createElement('textarea');
        textarea.value = captionText;
        textarea.style.position = 'fixed';
        textarea.style.opacity = '0';
        document.body.append(textarea);
        textarea.select();
        document.execCommand('copy');
        textarea.remove();
        if (desktopShareStatus) desktopShareStatus.textContent = '✓ Legenda copiada para a área de transferência.';
        return true;
      } catch (error) {
        if (desktopShareStatus) desktopShareStatus.textContent = 'Não foi possível copiar a legenda automaticamente.';
        return false;
      }
    }
  };

  const copyGeneratedImage = async () => {
    try {
      if (!navigator.clipboard || typeof ClipboardItem === 'undefined' || !window.isSecureContext) {
        return false;
      }

      render();
      const blob = await canvasBlob();
      const item = new ClipboardItem({ 'image/png': blob });
      await navigator.clipboard.write([item]);
      return true;
    } catch (error) {
      console.warn('Não foi possível copiar a imagem para a área de transferência:', error);
      return false;
    }
  };

  const openDesktopNetwork = async network => {
    // Para o X, a aba precisa ser criada imediatamente no clique.
    // Se esperarmos operações assíncronas de salvar/copiar, Chrome pode bloquear window.open.
    let xWindow = null;
    if (network === 'x') {
      xWindow = window.open('about:blank', '_blank');
      if (xWindow) {
        try {
          xWindow.opener = null;
          xWindow.document.title = 'Abrindo X...';
          xWindow.document.body.innerHTML =
            '<p style="font-family:Arial,sans-serif;padding:24px">Abrindo o X...</p>';
        } catch (_) {}
      }
    }

    const saved = await ensureDesktopSaved();
    if (!saved) {
      if (xWindow && !xWindow.closed) xWindow.close();
      return;
    }

    const imageCopied = await copyGeneratedImage();
    const text = encodeURIComponent(captionText);

    const urls = {
      instagram: 'https://www.instagram.com/',
      facebook: 'https://www.facebook.com/',
      x: `https://x.com/intent/tweet?text=${text}`,
      whatsapp: `https://web.whatsapp.com/send?text=${text}`
    };

    const target = urls[network];
    if (!target) {
      if (xWindow && !xWindow.closed) xWindow.close();
      return;
    }

    if (network === 'x') {
      if (xWindow && !xWindow.closed) {
        xWindow.location.replace(target);
      } else {
        // Fallback quando o navegador bloqueia pop-ups.
        window.location.assign(target);
      }
    } else {
      window.open(target, '_blank', 'noopener');
    }

    const labels = {
      instagram: 'Instagram',
      facebook: 'Facebook',
      x: 'X',
      whatsapp: 'WhatsApp Web'
    };

    if (imageCopied) {
      if (desktopShareStatus) {
        desktopShareStatus.textContent =
          `Imagem salva e copiada. ${labels[network]} aberto. Use Ctrl+V (ou ⌘+V no Mac) para colar a imagem na publicação.`;
      }
    } else if (desktopShareStatus) {
      desktopShareStatus.textContent =
        `Imagem salva. ${labels[network]} aberto. Anexe o arquivo salvo à publicação.`;
    }
  };

  const makeMobileShareFile = async () => {
    render();
    const blob = await canvasBlob();
    return new File([blob], spec().filename, { type: 'image/png', lastModified: Date.now() });
  };

  const mobileDownloadFallback = async () => {
    render();
    const blob = await canvasBlob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = spec().filename;
    a.rel = 'noopener';
    a.style.display = 'none';
    document.body.append(a);
    a.click();
    a.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 5000);
  };

  const shareToFacebookMobile = async () => {
    if (!loaded || !selectedFormat) return false;

    try {
      // Copy the complete caption first. Facebook mobile frequently ignores
      // text when a Web Share payload also contains a local image file.
      let captionCopied = false;
      try {
        await navigator.clipboard.writeText(captionText);
        captionCopied = true;
      } catch (_) {
        try {
          const textarea = document.createElement('textarea');
          textarea.value = captionText;
          textarea.style.position = 'fixed';
          textarea.style.opacity = '0';
          document.body.append(textarea);
          textarea.select();
          captionCopied = document.execCommand('copy');
          textarea.remove();
        } catch (_) {}
      }

      const file = await makeMobileShareFile();
      const canShareFile =
        !!navigator.share &&
        (!navigator.canShare || navigator.canShare({ files: [file] }));

      if (canShareFile) {
        if (mobileShareStatus) {
          mobileShareStatus.textContent = captionCopied
            ? 'Legenda copiada. Na tela que abrir, escolha Facebook. Se o texto não aparecer automaticamente, cole a legenda no post.'
            : 'Na tela que abrir, escolha Facebook. A imagem será enviada como arquivo.';
        }

        // Important: FILE ONLY. Sending text+file together is inconsistently
        // handled by the Facebook share target on Android/iOS.
        await navigator.share({
          files: [file],
          title: 'Eu apoio Fabiano Trompetista 13007'
        });

        return true;
      }

      // Fallback: save image + open Facebook homepage/app association.
      await mobileDownloadFallback();
      if (mobileShareStatus) {
        mobileShareStatus.textContent = captionCopied
          ? 'A imagem foi baixada e a legenda foi copiada. Abra o Facebook, selecione a imagem salva e cole a legenda.'
          : 'A imagem foi baixada. Abra o Facebook e selecione a imagem salva para publicar.';
      }
      window.setTimeout(() => {
        window.open('https://www.facebook.com/', '_blank', 'noopener,noreferrer');
      }, 150);
      return false;
    } catch (error) {
      if (error?.name === 'AbortError') {
        if (mobileShareStatus) mobileShareStatus.textContent = 'Compartilhamento cancelado.';
        return false;
      }

      console.error('Falha no compartilhamento mobile do Facebook:', error);

      try {
        await mobileDownloadFallback();
        if (mobileShareStatus) {
          mobileShareStatus.textContent =
            'O Facebook não aceitou o envio direto. A imagem foi baixada; abra o Facebook, selecione-a e use COPIAR LEGENDA.';
        }
      } catch (_) {
        if (mobileShareStatus) {
          mobileShareStatus.textContent = 'Não foi possível preparar a imagem para o Facebook.';
        }
      }
      return false;
    }
  };

  const nativeShareFile = async ({ network = '', saveOnly = false } = {}) => {
    if (!loaded || !selectedFormat) return false;

    try {
      const file = await makeMobileShareFile();
      const canShareFile =
        !!navigator.share &&
        (!navigator.canShare || navigator.canShare({ files: [file] }));

      if (canShareFile) {
        if (saveOnly && mobileSaveStatus) {
          if (/iPhone|iPad|iPod/i.test(navigator.userAgent)) {
            mobileSaveStatus.textContent = 'Na tela do iPhone/iPad, escolha “Salvar Imagem”.';
          } else if (/Android/i.test(navigator.userAgent)) {
            mobileSaveStatus.textContent = 'Na tela do Android, escolha Fotos, Galeria ou a opção de salvar disponível.';
          } else {
            mobileSaveStatus.textContent = 'Na tela do sistema, escolha a opção para salvar a imagem.';
          }
        }

        if (network && mobileShareStatus) {
          const names = {
            instagram: 'Instagram',
            facebook: 'Facebook',
            x: 'X',
            whatsapp: 'WhatsApp'
          };
          mobileShareStatus.textContent = `Na tela que abrir, escolha ${names[network]}.`;
        }

        const shareData = {
          files: [file],
          title: 'Eu apoio Fabiano Trompetista 13007'
        };

        if (!saveOnly) {
          shareData.text = captionText;
        }

        await navigator.share(shareData);

        if (saveOnly && mobileSaveStatus) {
          mobileSaveStatus.textContent = 'Ação concluída pelo sistema do aparelho.';
        }
        return true;
      }

      await mobileDownloadFallback();

      if (saveOnly && mobileSaveStatus) {
        mobileSaveStatus.textContent =
          'Seu navegador não oferece salvamento direto em Fotos/Galeria. A imagem foi baixada em PNG.';
      }

      if (network && mobileShareStatus) {
        mobileShareStatus.textContent =
          'Seu navegador não permite anexar a imagem diretamente. O arquivo foi baixado para você compartilhar manualmente.';
      }
      return false;
    } catch (error) {
      if (error?.name === 'AbortError') {
        if (saveOnly && mobileSaveStatus) mobileSaveStatus.textContent = 'Salvamento cancelado.';
        if (network && mobileShareStatus) mobileShareStatus.textContent = 'Compartilhamento cancelado.';
        return false;
      }

      console.error('Falha no fluxo mobile de salvar/compartilhar:', error);

      try {
        await mobileDownloadFallback();

        if (saveOnly && mobileSaveStatus) {
          mobileSaveStatus.textContent =
            'Não foi possível abrir o salvamento nativo. A imagem foi baixada em PNG.';
        }

        if (network && mobileShareStatus) {
          mobileShareStatus.textContent =
            'Não foi possível abrir o compartilhamento nativo. A imagem foi baixada em PNG.';
        }
      } catch (fallbackError) {
        console.error('Falha no fallback mobile:', fallbackError);
        if (saveOnly && mobileSaveStatus) {
          mobileSaveStatus.textContent = 'Não foi possível salvar a imagem. Recarregue a página e tente novamente.';
        }
        if (network && mobileShareStatus) {
          mobileShareStatus.textContent = 'Não foi possível gerar a imagem.';
        }
      }
      return false;
    }
  };

  const saveProfileImage = async () => {
    if (!loaded || selectedFormat !== 'profile') return;

    const isMobile =
      window.matchMedia('(max-width: 820px)').matches ||
      /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);

    if (profileSaveStatus) profileSaveStatus.textContent = '';

    if (isMobile) {
      const ok = await nativeShareFile({ saveOnly: true });
      if (profileSaveStatus) {
        profileSaveStatus.textContent = ok
          ? 'Ação concluída pelo sistema do aparelho.'
          : 'Se necessário, use o arquivo PNG baixado para trocar sua foto de perfil.';
      }
      return;
    }

    const saved = await saveImageDesktop();
    if (profileSaveStatus) {
      profileSaveStatus.textContent = saved
        ? '✓ Foto de perfil salva. Clique em Avançar para acessar suas redes sociais.'
        : 'Salvamento cancelado ou não concluído.';
    }
  };

  const openProfileNetwork = network => {
    const webUrls = {
      instagram: 'https://www.instagram.com/',
      facebook: 'https://www.facebook.com/',
      x: 'https://x.com/',
      whatsapp: 'https://web.whatsapp.com/'
    };

    const appUrls = {
      instagram: 'instagram://app',
      facebook: 'fb://feed',
      x: 'twitter://timeline',
      whatsapp: 'whatsapp://'
    };

    const webTarget = webUrls[network];
    const appTarget = appUrls[network];
    if (!webTarget) return;

    const isMobile =
      window.matchMedia('(max-width: 820px)').matches ||
      /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);

    if (!isMobile) {
      window.open(webTarget, '_blank', 'noopener,noreferrer');
      return;
    }

    let appOpened = false;
    let fallbackTimer = null;

    const stopFallback = () => {
      if (document.hidden) {
        appOpened = true;
        if (fallbackTimer) {
          clearTimeout(fallbackTimer);
          fallbackTimer = null;
        }
      }
    };

    document.addEventListener('visibilitychange', stopFallback, { once: true });

    fallbackTimer = window.setTimeout(() => {
      if (!appOpened && document.visibilityState === 'visible') {
        window.open(webTarget, '_blank', 'noopener,noreferrer');
      }
    }, 1400);

    window.location.href = appTarget;
  };

  const shareOrSave = async () => {
    if (!loaded || !selectedFormat) return;
    render();

    try {
      const blob = await canvasBlob();
      const file = new File([blob], spec().filename, { type: 'image/png' });

      if (navigator.share && (!navigator.canShare || navigator.canShare({ files: [file] }))) {
        if (status) status.textContent = 'Escolha onde salvar ou compartilhar na tela do seu aparelho.';
        await navigator.share({
          files: [file],
          title: 'Eu apoio Fabiano Trompetista 13007',
          text: captionText
        });
        return;
      }

      await forceDownload();
      if (status) status.textContent = 'A imagem foi baixada em PNG. Você já pode publicá-la ou compartilhá-la.';
    } catch (error) {
      if (error?.name === 'AbortError') return;
      console.error('Falha ao compartilhar/salvar:', error);
      try {
        await forceDownload();
        if (status) status.textContent = 'O compartilhamento nativo não estava disponível; a imagem foi baixada em PNG.';
      } catch (_) {
        if (status) status.textContent = 'Não foi possível gerar o arquivo. Recarregue a página e tente novamente.';
      }
    }
  };

  openButton.addEventListener('click', openWizard);
  closeButtons.forEach(button => button.addEventListener('click', closeWizard));

  document.addEventListener('keydown', event => {
    if (!wizard.hidden && event.key === 'Escape') closeWizard();
  });

  input.addEventListener('change', () => loadFile(input.files?.[0]));

  formatButtons.forEach(button => {
    button.addEventListener('click', () => chooseFormat(button.dataset.wizardFormat));
  });

  nextButton?.addEventListener('click', () => {
    if (step === 1 && loaded) goToStep(2);
    else if (step === 2 && selectedFormat) goToStep(3);
    else if (step === 3) goToStep(4);
    else if (step === 4) goToStep(isProfileFlow() ? 6 : 5);
    else if (step === 5 && captionChoice) goToStep(6);
  });

  backButton?.addEventListener('click', () => {
    if (isProfileFlow() && step === 6) {
      goToStep(4);
      return;
    }
    goToStep(step - 1);
  });

  zoom.addEventListener('input', () => {
    if (!loaded || !selectedFormat) return;
    zoomFactor = Number(zoom.value) / 100;
    if (zoomValue) zoomValue.value = `${zoom.value}%`;
    clampOffsets();
    render();
  });

  resetButton?.addEventListener('click', resetView);
  shareButton?.addEventListener('click', shareOrSave);
  saveButton?.addEventListener('click', saveImageDesktop);
  desktopShareButtons.forEach(button => {
    button.addEventListener('click', () => openDesktopNetwork(button.dataset.desktopShare));
  });
  mobileSaveButton?.addEventListener('click', () => nativeShareFile({ saveOnly: true }));
  mobileShareButtons.forEach(button => {
    button.addEventListener('click', () => {
      const network = button.dataset.mobileShare;
      if (network === 'facebook') {
        shareToFacebookMobile();
        return;
      }
      nativeShareFile({ network });
    });
  });
  profileSaveButton?.addEventListener('click', saveProfileImage);
  profileNetworkButtons.forEach(button => {
    button.addEventListener('click', () => openProfileNetwork(button.dataset.profileNetwork));
  });

  copyCaptionStep6Button?.addEventListener('click', async () => {
    const copied = await copyCaption();
    if (desktopShareStatus) {
      desktopShareStatus.textContent = copied
        ? '✓ Legenda copiada para a área de transferência.'
        : 'Não foi possível copiar a legenda automaticamente.';
    }
  });

  copyCaptionStep6MobileButton?.addEventListener('click', async () => {
    const copied = await copyCaption();
    if (mobileShareStatus) {
      mobileShareStatus.textContent = copied
        ? '✓ Legenda copiada para a área de transferência.'
        : 'Não foi possível copiar a legenda automaticamente.';
    }
  });

  captionCopyContinueButton?.addEventListener('click', async () => {
    const copied = await copyCaption();

    if (copied) {
      captionChoice = 'copied';
      captionCopyContinueButton.classList.add('is-selected');
      captionSkipButton?.classList.remove('is-selected');

      if (captionChoiceStatus) {
        captionChoiceStatus.textContent = '✓ Legenda copiada. Agora clique em AVANÇAR.';
      }
    } else if (captionChoiceStatus) {
      captionChoiceStatus.textContent =
        'Não foi possível copiar automaticamente. Você pode tentar novamente ou escolher criar sua própria legenda.';
    }

    updateNavigation();
  });

  captionSkipButton?.addEventListener('click', () => {
    captionChoice = 'own';
    captionSkipButton.classList.add('is-selected');
    captionCopyContinueButton?.classList.remove('is-selected');

    if (captionChoiceStatus) {
      captionChoiceStatus.textContent = 'Você escolheu criar sua própria legenda. Agora clique em AVANÇAR.';
    }

    updateNavigation();
  });

  editorFrame?.addEventListener('pointerdown', event => {
    if (!loaded || !selectedFormat) return;
    dragging = true;
    pointerId = event.pointerId;
    lastX = event.clientX;
    lastY = event.clientY;
    editorFrame.classList.add('is-dragging');
    editorFrame.setPointerCapture?.(pointerId);
    event.preventDefault();
  });

  editorFrame?.addEventListener('pointermove', event => {
    if (!dragging || event.pointerId !== pointerId || !loaded || !selectedFormat) return;

    const rect = editorFrame.getBoundingClientRect();
    offsetX += (event.clientX - lastX) * (W() / rect.width);
    offsetY += (event.clientY - lastY) * (H() / rect.height);
    lastX = event.clientX;
    lastY = event.clientY;
    clampOffsets();
    render();
    event.preventDefault();
  });

  const endDrag = event => {
    if (!dragging) return;
    if (event?.pointerId !== undefined && pointerId !== null && event.pointerId !== pointerId) return;
    dragging = false;
    editorFrame?.classList.remove('is-dragging');
    try { editorFrame?.releasePointerCapture?.(pointerId); } catch (_) {}
    pointerId = null;
  };

  editorFrame?.addEventListener('pointerup', endDrag);
  editorFrame?.addEventListener('pointercancel', endDrag);
  editorFrame?.addEventListener('lostpointercapture', endDrag);

  // As três artes atuais já possuem listeners individuais de load.
  // Não usar a antiga variável campaignArt: ela não existe mais e interrompia initApp(),
  // impedindo a inicialização dos carrosséis que vêm depois.


  window.addEventListener('resize', () => {
    window.clearTimeout(window.__supporterWizardFitTimer);
    window.__supporterWizardFitTimer = window.setTimeout(fitActiveStepToViewport, 80);
  });

  window.addEventListener('orientationchange', () => {
    window.setTimeout(fitActiveStepToViewport, 180);
  });

  window.addEventListener('beforeunload', () => {
    if (objectUrl) URL.revokeObjectURL(objectUrl);
  }, { once: true });

  setCanvasSize();
  updateNavigation();
}


// ===== anchor-stabilizer.js =====
function initAnchorStabilizer() {
  const getTarget = () => {
    const hash = window.location.hash;
    if (!hash || hash.length < 2) return null;
    try {
      return document.querySelector(hash);
    } catch (_) {
      return null;
    }
  };

  const getHeaderOffset = () => {
    const header = document.querySelector('.site-header');
    if (!header) return 16;
    return Math.max(0, Math.round(header.getBoundingClientRect().height)) + 12;
  };

  const scrollToHashTarget = (behavior = 'auto') => {
    const target = getTarget();
    if (!target) return;

    const top = window.scrollY + target.getBoundingClientRect().top - getHeaderOffset();
    window.scrollTo({
      top: Math.max(0, top),
      behavior
    });
  };

  const stabilizeHashPosition = () => {
    if (!getTarget()) return;

    requestAnimationFrame(() => scrollToHashTarget('auto'));

    [180, 450, 900, 1500].forEach(delay => {
      window.setTimeout(() => scrollToHashTarget('auto'), delay);
    });
  };

  window.addEventListener('load', stabilizeHashPosition);

  window.addEventListener('hashchange', () => {
    window.setTimeout(() => scrollToHashTarget('smooth'), 40);
    window.setTimeout(() => scrollToHashTarget('auto'), 500);
  });

  if (document.readyState === 'complete') {
    stabilizeHashPosition();
  }
}

// ===== app.js =====
function initLazyImages() {
  qsa('img[loading="lazy"]').forEach(image => {
    image.classList.add('lazy-image');
    const loaded = () => image.classList.add('is-loaded');
    image.complete ? loaded() : image.addEventListener('load', loaded, { once: true });
  });
}

function initApp() {
  initLoader();
  initAnchorStabilizer();
  initNavbar();
  initScroll();
  initReveal();
  initCounters();
  initHero();
  initHeroVideoPlaylist();
  const lightbox = initLightbox();
  initGallery(lightbox.open);
  initLazyImages();
  initWhatsappFloatText();
  initVoterNote();
  initSupporterPhotoCreator();
  initMediaAuthenticityNotice();
  initCampaignPhotosCarousel();
  initLulaCarousels();
  initAboutCarousel();
  initDynamicAgenda();
  const year = qs('#current-year');
  if (year) year.textContent = String(new Date().getFullYear());
}

document.readyState === 'loading'
  ? document.addEventListener('DOMContentLoaded', initApp, { once: true })
  : initApp();
